/**
 * @param {*} n 砝码的种数
 * @param {*} m 每种砝码的重量
 * @param {*} x 每种砝码对应的数量
 */
function getResult(n, m, x) {
    m = [0, ...m];
    x = [0, ...x];

    let bag = 0;
    for (let i = 1; i <= n; i++) bag += m[i] * x[i];

    const dp = new Array(bag + 1).fill(false);
    dp[0] = true;

    for (let i = 1; i <= n; i++) {
        for (let j = bag; j >= m[i]; j--) {
            for (let k = 1; k <= x[i]; k++) {
                if (j >= m[i] * k) {
                    if (dp[j - m[i] * k]) dp[j] = true;
                }
            }
        }
    }

    return dp.filter((f) => f).length;
}

