/**
 * @param {*} n 砝码的种数
 * @param {*} m 每种砝码的重量
 * @param {*} x 每种砝码对应的数量
 */
function getResult(n, m, x) {
  let bag = 0;
  const newM = [];

  for (let i = 0; i < n; i++) {
    // 背包承重等于所有砝码重量之和
    bag += m[i] * x[i];

    // 将1种物品N个，进行二进制优化
    for (let j = 1; j <= x[i]; j <<= 1) {
      newM.push(m[i] * j);
      x[i] -= j;
    }

    if (x[i] != 0) {
      newM.push(x[i] * m[i]);
    }
  }

  // 01背包滚动数组优化求解
  const dp = new Array(bag + 1).fill(false);
  // 0重量组合肯定存在
  dp[0] = true;

  for (let w of newM) {
    for (let j = bag; j >= w; j--) {
      // 如果j-w组合重量存在，那么j重量组合也一定存在
      if (dp[j - w]) dp[j] = true;
    }
  }

  return dp.filter((f) => f).length;
}

